<?php
ob_start(static function (string $html) use ($lang): string {
    $brand = trim((string)setting('business_name', 'TofiDesk'));
    if ($brand !== '') {
        $html = str_replace(['Kaş Nakliyat', 'KAŞ NAKLİYAT'], [e($brand), e($brand)], $html);
    }
    $location = trim((string)setting('location_label', ''));
    if ($location !== '') $html = str_replace('KAŞ · ANTALYA', e($location), $html);
    $eyebrow = trim((string)setting('homepage_eyebrow_'.$lang, ''));
    if ($eyebrow !== '') $html = str_replace(e(t('hero_eyebrow', $lang)), e($eyebrow), $html);
    $regionsTitle = trim((string)setting('homepage_regions_title_'.$lang, ''));
    $regionsText = trim((string)setting('homepage_regions_text_'.$lang, ''));
    $processTitle = trim((string)setting('homepage_process_title_'.$lang, ''));
    $serviceTitle = trim((string)setting('homepage_service_title_'.$lang, ''));
    $serviceIntro = trim((string)setting('homepage_service_intro_'.$lang, ''));
    if ($regionsTitle !== '') $html = str_replace(e(t('regions_title', $lang)), e($regionsTitle), $html);
    if ($regionsText !== '') $html = str_replace(e(t('regions_text', $lang)), e($regionsText), $html);
    if ($processTitle !== '') $html = str_replace(e(t('process_title', $lang)), e($processTitle), $html);
    if ($serviceTitle !== '') $html = str_replace(e(t('service_title', $lang)), e($serviceTitle), $html);
    if ($serviceIntro !== '') $html = str_replace(e(t('service_intro', $lang)), e($serviceIntro), $html);
    $logo = trim((string)setting('logo_url', ''));
    if ($logo !== '' && filter_var($logo, FILTER_VALIDATE_URL)) {
        $html = str_replace(['/assets/logo.svg', '/assets/logo-light.svg'], [e($logo), e($logo)], $html);
    }
    $hero = trim((string)setting('hero_image_url', ''));
    if ($hero !== '' && filter_var($hero, FILTER_VALIDATE_URL)) $html = str_replace('/assets/mediterranean.svg', e($hero), $html);
    $profiles = [
        'facebook_url' => ['Facebook', 'Facebook'],
        'instagram_url' => ['Instagram', 'Instagram'],
        'linkedin_url' => ['LinkedIn', 'LinkedIn'],
        'youtube_url' => ['YouTube', 'YouTube'],
        'pinterest_url' => ['Pinterest', 'Pinterest'],
    ];
    $links = '';
    foreach ($profiles as $settingKey => [$label, $aria]) {
        $url = trim((string)setting($settingKey, ''));
        if ($url === '' || !filter_var($url, FILTER_VALIDATE_URL) || !in_array(strtolower((string)parse_url($url, PHP_URL_SCHEME)), ['https', 'http'], true)) continue;
        $host = strtolower((string)parse_url($url, PHP_URL_HOST));
        if ($host === '' || preg_match('/[\r\n\"<>]/', $url)) continue;
        $links .= '<a class="social-link" href="'.e($url).'" target="_blank" rel="noopener noreferrer" aria-label="'.e($aria).'">'.e($label).'</a>';
    }
    $legal = '<nav class="legal-links" aria-label="Legal"><a href="/'.e($lang).'/kullanim-sartlari/">'.e(t('terms_title', $lang)).'</a><a href="/'.e($lang).'/destek-sla/">'.e(t('sla_title', $lang)).'</a></nav>';
    $cookieHtml = '<span>'.e(t('cookie_notice',$lang)).'</span><div class="cookie-actions"><button type="button" data-cookie-necessary>'.e(t('cookie_necessary',$lang)).'</button><button type="button" data-cookie-accept>'.e(t('cookie_accept',$lang)).'</button></div>';
    if ($links === '') { $cookie = isset($_COOKIE['tofidesk_cookie_consent']) ? '' : '<aside class="cookie-consent" data-cookie-consent>'.$cookieHtml.'</aside>'; return str_replace(['</footer>','</body>'], [$legal.'</footer>',$cookie.'</body>'], $html); }
    $block = '<nav class="social-links" aria-label="Social media">'.$links.'</nav>'.$legal;
    $cookie = isset($_COOKIE['tofidesk_cookie_consent']) ? '' : '<aside class="cookie-consent" data-cookie-consent>'.$cookieHtml.'</aside>';
    return str_replace(['</footer>','</body>'], [$block.'</footer>',''.$cookie.'</body>'], $html);
});
